import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../../../core/models/ayah.dart';
import '../../../core/models/surah.dart';

/// Result of parsing the bundled Quran assets.
typedef QuranData = ({List<Surah> surahs, List<Ayah> ayahs});

/// Parses the bundled Quran JSON assets into Isar model lists.
///
/// Both files are generated by tools/build_quran_assets.py from unmodified
/// Tanzil (https://tanzil.net) downloads. Ayah text is never altered here.
///
/// quran_simple.json — array of surah objects:
/// [{"number":1,"name":"الفاتحة","englishName":"Al-Faatiha",
///   "englishNameTranslation":"The Opening","numberOfAyahs":7,
///   "revelationType":"Meccan","ayahs":[{"number":1,"text":"..."}]}]
///
/// translation_en.json — array matching surah numbers:
/// [{"number":1,"ayahs":[{"number":1,"text":"..."}]}]
class QuranJsonParser {
  static const _quranAsset = 'assets/quran/quran_simple.json';
  static const _translationAsset = 'assets/quran/translation_en.json';

  /// Loads both assets and parses them on a background isolate so the
  /// ~2.5 MB of JSON never blocks the UI thread.
  static Future<QuranData> load() async {
    final quranRaw = await rootBundle.loadString(_quranAsset);
    final transRaw = await rootBundle.loadString(_translationAsset);
    return compute(_parseMessage, (quranRaw, transRaw));
  }

  static QuranData _parseMessage((String, String) raw) =>
      parse(raw.$1, raw.$2);

  /// Pure parser: Quran JSON + translation JSON → surahs and ayahs.
  static QuranData parse(String quranJson, String translationJson) {
    final quranList = jsonDecode(quranJson) as List<dynamic>;
    final transList = jsonDecode(translationJson) as List<dynamic>;

    // Translation lookup: surahNumber → {ayahNumber → text}
    final transLookup = <int, Map<int, String>>{};
    for (final s in transList) {
      final m = s as Map<String, dynamic>;
      transLookup[m['number'] as int] = {
        for (final a in (m['ayahs'] as List<dynamic>))
          (a as Map<String, dynamic>)['number'] as int: a['text'] as String,
      };
    }

    final surahs = <Surah>[];
    final ayahs = <Ayah>[];
    for (final s in quranList) {
      final m = s as Map<String, dynamic>;
      final surahNum = m['number'] as int;
      surahs.add(Surah()
        ..number = surahNum
        ..name = m['name'] as String
        ..englishName = m['englishName'] as String
        ..englishNameTranslation = m['englishNameTranslation'] as String
        ..numberOfAyahs = m['numberOfAyahs'] as int
        ..revelationType = m['revelationType'] as String);

      for (final a in (m['ayahs'] as List<dynamic>?) ?? const []) {
        final am = a as Map<String, dynamic>;
        final ayahNum = am['number'] as int;
        ayahs.add(Ayah()
          ..surahNumber = surahNum
          ..ayahNumber = ayahNum
          ..arabicText = am['text'] as String
          ..translation = transLookup[surahNum]?[ayahNum]);
      }
    }
    return (surahs: surahs, ayahs: ayahs);
  }
}
